import {jest} from '@jest/globals';
import {Ajv} from 'ajv';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry static validator', () => {
  it('reuses the static validator across ten calls (specs/hal-engine-tool-input-validation/spec.md#7)', async () => {
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    try {
      const registry = new ToolRegistry();
      registry.register(
        {name: 'weather', description: 'Forecast', inputSchema: {type: 'object'}},
        async () => 'sunny'
      );
      const registrations = compile.mock.calls.length;
      for (let call = 0; call < 10; call++) {
        await registry.execute('weather', {});
      }
      expect({registrations, total: compile.mock.calls.length}).toEqual({registrations: 1, total: 1});
    } finally {
      compile.mockRestore();
    }
  });
});
EOF
